  var ECO11_QUESTION_BANK = [
    { q: 'The basic economic problem is best described as:', options: ['Unlimited wants but finite resources, meaning choices must be made', 'Too many goods being produced', 'Governments always spending too much money', 'Prices always rising over time'], correct: 0, explain: 'The economic problem is that human wants are unlimited while resources to satisfy them are finite (scarce), so choices have to be made.', misconception: 'The economic problem is about scarcity and choice, not about inflation or government spending specifically.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'Opportunity cost is best defined as:', options: ['The value of the next best alternative given up when a choice is made', 'The total cost of producing a good', 'The price a consumer pays for a good', 'The cost of transporting goods to market'], correct: 0, explain: 'Opportunity cost is the benefit of the next best alternative that is sacrificed when a choice is made.', misconception: 'Opportunity cost is not the same as the price paid — it is about the value of what was given up.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'A production possibility curve (PPC) shows:', options: ['The maximum combinations of two goods an economy can produce with its existing resources', 'The exact quantity a business will sell', 'How prices change over time', 'The amount of tax collected by government'], correct: 0, explain: 'A PPC illustrates the maximum possible output combinations of two goods or services given fixed resources and technology.', misconception: 'A PPC is about production potential, not about prices, sales, or tax revenue.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'A point inside (within) the production possibility curve represents:', options: ['Unemployed or underused resources', 'The maximum possible output', 'An unobtainable level of output', 'A point of perfect efficiency'], correct: 0, explain: 'A point inside the PPC shows that resources are not being fully or efficiently used — output could increase without needing more resources.', misconception: 'Points inside the curve show inefficiency, not maximum output — that would be on the curve itself.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'An outward shift of the whole production possibility curve represents:', options: ['Positive economic growth', 'A recession', 'Rising unemployment only', 'A fall in resources available'], correct: 0, explain: 'An outward shift of the PPC shows an increase in the economy’s productive potential — positive economic growth.', misconception: 'A shift outward reflects growth in productive capacity, not a downturn or resource loss, which would shift the curve inward.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'Which of the following could cause an outward shift of a production possibility curve?', options: ['An increase in the quantity or quality of factors of production, such as new technology', 'A natural disaster destroying factories', 'A fall in the size of the labour force', 'A decrease in capital stock'], correct: 0, explain: 'Improvements in the quantity or quality of resources — for example new technology or a larger, better-trained workforce — increase productive potential and shift the PPC outward.', misconception: 'Losing resources (labour, capital, or from a disaster) would shift the PPC inward, showing negative growth, not outward.', tag: 'Scarcity, opportunity cost & PPC' },
    { q: 'Economists traditionally assume that consumers aim to:', options: ['Maximise their benefit (utility) from spending', 'Maximise government tax revenue', 'Minimise their own happiness', 'Always buy the most expensive good available'], correct: 0, explain: 'The standard economic assumption is that rational consumers aim to maximise the benefit, or utility, they get from their spending.', misconception: 'This assumption is about maximising personal benefit, not about tax revenue or deliberately reducing satisfaction.', tag: 'Economic assumptions' },
    { q: 'Which of the following might cause a consumer not to maximise their benefit in practice?', options: ['Acting out of habit rather than carefully calculating benefits', 'Always comparing every possible option in detail', 'Having perfect information about every good', 'Never being influenced by other people'], correct: 0, explain: 'In reality, consumers often act out of habit, copy others, or fail to calculate benefits accurately, meaning they may not truly maximise benefit.', misconception: 'Perfect information and careful comparison would support utility maximisation — it is the absence of these that causes consumers to deviate from the assumption.', tag: 'Economic assumptions' },
    { q: 'Traditionally, economists assume that businesses aim to:', options: ['Maximise profit', 'Maximise costs', 'Minimise all sales', 'Avoid making any profit'], correct: 0, explain: 'The standard economic assumption is that firms aim to maximise profit — the difference between total revenue and total costs.', misconception: 'Firms aim to maximise, not minimise, financial success — minimising costs alone without regard to revenue is not the same as profit maximisation.', tag: 'Economic assumptions' },
    { q: 'A reason a business might not purely maximise profit is:', options: ['Managers may prioritise growing sales or revenue instead', 'All businesses are legally required to maximise profit', 'Profit maximisation is impossible to define', 'Customers always demand the highest possible prices'], correct: 0, explain: 'Some managers pursue sales or revenue maximisation, or prioritise other goals like customer care or charitable work, rather than purely maximising profit.', misconception: 'There is no legal requirement to maximise profit — other business objectives can take priority in practice.', tag: 'Economic assumptions' },
    { q: 'The law of demand states that, other things being equal:', options: ['As price falls, quantity demanded rises, and vice versa', 'As price rises, quantity demanded also rises', 'Price and demand are always unrelated', 'Demand always stays constant regardless of price'], correct: 0, explain: 'The law of demand states that there is an inverse relationship between price and quantity demanded, all else being equal.', misconception: 'Demand and price move in opposite directions, not the same direction, under the standard law of demand.', tag: 'Demand' },
    { q: 'A movement along a demand curve is caused by:', options: ['A change in the price of the good itself', 'A change in consumer income', 'A change in the price of a substitute good', 'A change in advertising'], correct: 0, explain: 'A movement along the demand curve (an extension or contraction) is caused only by a change in the price of the good itself.', misconception: 'Changes in income, the price of related goods, or advertising shift the whole demand curve rather than causing a movement along it.', tag: 'Demand' },
    { q: 'An increase in demand is shown on a diagram as:', options: ['A shift of the whole demand curve to the right', 'A movement upward along the same demand curve', 'A shift of the whole demand curve to the left', 'No change to the curve at all'], correct: 0, explain: 'An increase in demand, caused by a non-price factor, shifts the entire demand curve to the right, showing more is demanded at every price.', misconception: 'A shift to the left would represent a decrease in demand, and a movement along the curve represents a change in price, not a shift in demand itself.', tag: 'Demand' },
    { q: 'If two goods are substitutes, a rise in the price of Good A would generally:', options: ['Increase demand for Good B', 'Decrease demand for Good B', 'Have no effect on Good B', 'Only affect the price of Good A'], correct: 0, explain: 'When the price of a substitute (Good A) rises, consumers switch towards the alternative, increasing demand for Good B.', misconception: 'This is the opposite effect to complementary goods, where a price rise in one good tends to decrease demand for the other.', tag: 'Demand' },
    { q: 'If two goods are complements, a rise in the price of Good A would generally:', options: ['Decrease demand for Good B', 'Increase demand for Good B', 'Have no effect on Good B', 'Cause Good B to become a substitute'], correct: 0, explain: 'Complementary goods are used together, so a price rise in one (making it less attractive to buy) tends to reduce demand for the other as well.', misconception: 'This is the opposite of the substitute-goods relationship, where a price rise in one good increases demand for the alternative.', tag: 'Demand' },
    { q: 'The law of supply states that, other things being equal:', options: ['As price rises, quantity supplied also rises', 'As price rises, quantity supplied falls', 'Supply is unrelated to price', 'Supply always falls over time'], correct: 0, explain: 'The law of supply describes a positive (direct) relationship between price and quantity supplied — higher prices generally incentivise producers to supply more.', misconception: 'Supply and price move in the same direction under the law of supply, not opposite directions as with demand.', tag: 'Supply' },
    { q: 'A rise in the cost of raw materials used in production would cause:', options: ['A decrease in supply, shifting the supply curve left', 'An increase in supply, shifting the supply curve right', 'A movement along the existing supply curve only', 'No change to supply at all'], correct: 0, explain: 'Higher production costs make supplying goods less profitable at any given price, so the whole supply curve shifts left (a decrease in supply).', misconception: 'A change in production costs shifts the whole supply curve, rather than causing a movement along it, which is only caused by a change in the good’s own price.', tag: 'Supply' },
    { q: 'A government subsidy paid to producers would typically cause:', options: ['An increase in supply, shifting the supply curve right', 'A decrease in supply, shifting the supply curve left', 'A fall in demand', 'No change to production costs'], correct: 0, explain: 'A subsidy effectively reduces production costs, encouraging producers to supply more at each price, shifting the supply curve to the right.', misconception: 'Subsidies reduce costs and increase supply — they are the opposite of an indirect tax, which raises costs and reduces supply.', tag: 'Supply' },
    { q: 'An indirect tax imposed on producers would typically cause:', options: ['A decrease in supply, shifting the supply curve left', 'An increase in supply, shifting the supply curve right', 'A fall in the price of raw materials', 'An increase in consumer income'], correct: 0, explain: 'An indirect tax raises the cost of supplying a good, so the supply curve shifts left, showing a decrease in supply at every price.', misconception: 'Taxes raise costs and reduce supply — this is the opposite effect of a subsidy.', tag: 'Supply' },
    { q: 'Market equilibrium occurs where:', options: ['Quantity demanded equals quantity supplied', 'Quantity demanded is greater than quantity supplied', 'Quantity supplied is greater than quantity demanded', 'Price is at its lowest possible level'], correct: 0, explain: 'Market equilibrium is the point where the demand and supply curves intersect — the quantity consumers want to buy equals the quantity producers want to sell.', misconception: 'Equilibrium is defined by demand equalling supply, not by one being greater than the other, which describes excess demand or supply.', tag: 'Market equilibrium' },
    { q: 'Excess demand exists when, at the current price:', options: ['Quantity demanded is greater than quantity supplied', 'Quantity supplied is greater than quantity demanded', 'Price is above equilibrium', 'The market is in equilibrium'], correct: 0, explain: 'Excess demand occurs when, at a given price, more is demanded than is supplied — often because price is set below equilibrium.', misconception: 'Excess demand happens when demand exceeds supply, which is the opposite of excess supply.', tag: 'Market equilibrium' },
    { q: 'Excess supply exists when, at the current price:', options: ['Quantity supplied is greater than quantity demanded', 'Quantity demanded is greater than quantity supplied', 'The market is in equilibrium', 'Price is below equilibrium'], correct: 0, explain: 'Excess supply occurs when producers offer more of a good than consumers are willing to buy at that price — often when price is above equilibrium.', misconception: 'Excess supply is the opposite of excess demand, and it typically occurs above, not below, the equilibrium price.', tag: 'Market equilibrium' },
    { q: 'If there is excess supply in a market, market forces would typically cause:', options: ['Price to fall until quantity demanded and supplied are equal again', 'Price to rise indefinitely', 'Supply to disappear completely', 'No change in price at all'], correct: 0, explain: 'With excess supply, unsold stock builds up, so producers lower prices to clear it, moving the market back towards equilibrium.', misconception: 'Market forces move price towards equilibrium, not away from it — excess supply pushes price down, not up.', tag: 'Market equilibrium' },
    { q: 'An increase in demand, with supply unchanged, would generally cause:', options: ['Equilibrium price and quantity to both rise', 'Equilibrium price and quantity to both fall', 'Equilibrium price to rise while quantity falls', 'No change to price or quantity'], correct: 0, explain: 'An increase in demand shifts the demand curve right, resulting in a higher equilibrium price and a higher equilibrium quantity, assuming supply is unchanged.', misconception: 'Both price and quantity move in the same direction when demand shifts, assuming supply stays constant.', tag: 'Market equilibrium' },
    { q: 'Price elasticity of demand (PED) measures:', options: ['The responsiveness of quantity demanded to a change in price', 'The responsiveness of supply to a change in cost', 'The total revenue earned by a business', 'The change in income over time'], correct: 0, explain: 'PED measures how much quantity demanded changes in response to a change in price.', misconception: 'PED is specifically about demand responding to price changes, not about supply, revenue, or income directly.', tag: 'Price elasticity of demand (PED)' },
    { q: 'The formula for price elasticity of demand is:', options: ['Percentage change in quantity demanded ÷ percentage change in price', 'Percentage change in price ÷ percentage change in quantity demanded', 'Change in quantity demanded ÷ change in income', 'Total revenue ÷ total cost'], correct: 0, explain: 'PED = % change in quantity demanded ÷ % change in price.', misconception: 'The formula divides the change in quantity demanded by the change in price, not the other way around.', tag: 'Price elasticity of demand (PED)' },
    { q: 'A good with a PED value greater than 1 (ignoring sign) is described as:', options: ['Price elastic — demand is relatively responsive to price', 'Price inelastic — demand barely changes with price', 'Perfectly inelastic', 'Unrelated to price'], correct: 0, explain: 'When the PED value is greater than 1, demand is described as price elastic, meaning quantity demanded changes proportionally more than price.', misconception: 'A PED value less than 1 (ignoring sign) would indicate inelastic, not elastic, demand.', tag: 'Price elasticity of demand (PED)' },
    { q: 'Demand for a good tends to be more price inelastic when:', options: ['There are few or no close substitutes available', 'There are many close substitutes available', 'The good takes up a large share of income', 'Consumers have a long time to adjust their spending'], correct: 0, explain: 'When few substitutes exist, consumers have little choice but to keep buying even if price rises, making demand price inelastic.', misconception: 'Having many substitutes, a large share of income spent, or a long time to adjust all tend to make demand more elastic, not inelastic.', tag: 'Price elasticity of demand (PED)' },
    { q: 'If demand is price inelastic and a firm raises its price, total revenue will:', options: ['Increase, because quantity demanded falls proportionally less than price rises', 'Decrease, because quantity demanded falls proportionally more than price rises', 'Stay exactly the same', 'Fall to zero'], correct: 0, explain: 'With inelastic demand, a price rise causes a smaller proportional fall in quantity demanded, so total revenue increases overall.', misconception: 'This effect on revenue only applies when demand is inelastic — with elastic demand, a price rise would reduce total revenue instead.', tag: 'Price elasticity of demand (PED)' },
    { q: 'Necessities, such as basic food staples, tend to have:', options: ['Relatively price inelastic demand', 'Relatively price elastic demand', 'Perfectly elastic demand', 'No measurable demand at all'], correct: 0, explain: 'Necessities are goods people need regardless of price changes, so demand tends to be relatively unresponsive (inelastic) to price.', misconception: 'Luxuries, not necessities, tend to have more elastic demand, since consumers can more easily cut back on them.', tag: 'Price elasticity of demand (PED)' },
    { q: 'Price elasticity of supply (PES) measures:', options: ['The responsiveness of quantity supplied to a change in price', 'The responsiveness of demand to a change in income', 'The change in a firm’s total costs', 'The responsiveness of exchange rates to interest rates'], correct: 0, explain: 'PES measures how much quantity supplied changes in response to a change in price.', misconception: 'PES relates to supply responding to price, not to demand, income, costs, or exchange rates directly.', tag: 'Price elasticity of supply (PES)' },
    { q: 'Supply tends to be more price elastic when:', options: ['Producers hold spare capacity and can increase output quickly', 'Producers have no spare capacity at all', 'The good takes a long time to produce', 'Stocks of the good cannot be stored'], correct: 0, explain: 'Spare capacity allows producers to increase output quickly in response to a price rise, making supply more elastic.', misconception: 'A lack of spare capacity, long production times, and an inability to store stock all tend to make supply more inelastic, not elastic.', tag: 'Price elasticity of supply (PES)' },
    { q: 'Primary products, such as agricultural crops, tend to have supply that is:', options: ['Relatively price inelastic in the short run, due to long production/growing times', 'Always perfectly elastic', 'Completely unaffected by weather or growing seasons', 'More elastic than most manufactured goods'], correct: 0, explain: 'Agricultural and other primary products often take a long time to produce (a growing season, for example), so supply cannot respond quickly to price changes, making it relatively inelastic in the short run.', misconception: 'Manufactured goods can usually be produced more quickly and flexibly than primary products, so they tend to have more elastic supply, not less.', tag: 'Price elasticity of supply (PES)' },
    { q: 'A firm with high levels of stock (inventory) available is likely to have supply that is:', options: ['More price elastic, since it can quickly release stock in response to a price rise', 'More price inelastic, regardless of stock levels', 'Completely unaffected by price changes', 'Impossible to measure'], correct: 0, explain: 'Firms holding stock can respond quickly to a price rise by releasing goods from storage, making supply more elastic.', misconception: 'Available stock generally increases the ability to respond to price changes, making supply more elastic, not less.', tag: 'Price elasticity of supply (PES)' },
    { q: 'In the short run, supply for most goods tends to be:', options: ['More inelastic than in the long run, since producers have less time to adjust', 'More elastic than in the long run', 'Completely fixed regardless of time period', 'Unrelated to time'], correct: 0, explain: 'Producers generally need time to adjust factors of production, so supply is more inelastic in the short run and becomes more elastic over a longer time period.', misconception: 'The relationship works the other way round to what might be expected: more time to adjust makes supply more, not less, elastic.', tag: 'Price elasticity of supply (PES)' },
    { q: 'Income elasticity of demand measures:', options: ['The responsiveness of quantity demanded to a change in consumer income', 'The responsiveness of price to a change in supply', 'The change in government tax revenue', 'The change in exchange rates'], correct: 0, explain: 'Income elasticity of demand measures how much quantity demanded changes in response to a change in consumer income.', misconception: 'It is specifically about demand responding to income changes, not price, tax, or exchange rate changes.', tag: 'Income elasticity of demand' },
    { q: 'A normal good has an income elasticity of demand that is:', options: ['Positive, since demand rises as income rises', 'Negative, since demand falls as income rises', 'Always exactly zero', 'Impossible to measure'], correct: 0, explain: 'Normal goods have positive income elasticity — as income rises, demand for the good also rises.', misconception: 'A negative income elasticity describes an inferior good, where demand falls as income rises, not a normal good.', tag: 'Income elasticity of demand' },
    { q: 'An inferior good has an income elasticity of demand that is:', options: ['Negative, since demand falls as income rises', 'Positive, since demand rises as income rises', 'Always greater than 1', 'The same as a luxury good'], correct: 0, explain: 'Inferior goods have negative income elasticity — as consumers become richer, they buy less of the good, often switching to better alternatives.', misconception: 'Positive income elasticity describes normal (including luxury) goods, not inferior goods.', tag: 'Income elasticity of demand' },
    { q: 'A luxury good typically has an income elasticity of demand that is:', options: ['Positive and greater than 1', 'Negative and less than -1', 'Exactly zero', 'Undefined'], correct: 0, explain: 'Luxury goods are a type of normal good where demand rises more than proportionally as income rises, giving an income elasticity greater than 1.', misconception: 'A negative value would indicate an inferior good, not a luxury, which is a normal good with a strong positive income elasticity.', tag: 'Income elasticity of demand' },
    { q: 'A mixed economy is best described as one where:', options: ['Resources are allocated by both the market (private sector) and the government (public sector)', 'All resources are allocated only by the government', 'All resources are allocated only by free markets with no government involvement', 'Resources are never allocated at all'], correct: 0, explain: 'A mixed economy combines market forces (private sector) and government intervention (public sector) to allocate resources.', misconception: 'A mixed economy is neither a purely planned/command economy (all government) nor a purely free-market economy (no government) — it blends both.', tag: 'The mixed economy' },
    { q: 'The public sector refers to organisations that are:', options: ['Owned and/or controlled by the government', 'Owned entirely by private individuals or shareholders', 'Owned by international investors only', 'Not subject to any government regulation'], correct: 0, explain: 'The public sector consists of organisations owned and/or run by the government, such as public services and state-owned enterprises.', misconception: 'Organisations owned by private individuals or shareholders make up the private sector, not the public sector.', tag: 'The mixed economy' },
    { q: 'A public good, such as street lighting or national defence, is characterised by:', options: ['Non-excludability and non-rivalry', 'Being easily excludable from non-payers', 'Being used up entirely by the first consumer', 'Being produced only by private businesses'], correct: 0, explain: 'Public goods are non-excludable (people cannot be stopped from using them, even if they don’t pay) and non-rival (one person’s use doesn’t reduce availability for others).', misconception: 'Public goods are typically under-provided by the private market precisely because they are non-excludable — private firms struggle to charge for them.', tag: 'The mixed economy' },
    { q: 'The "free-rider problem" refers to the fact that:', options: ['People can benefit from a public good without paying for it, discouraging private provision', 'Governments always overprovide public goods', 'Businesses always make excess profit from public goods', 'Consumers must always pay for public goods before using them'], correct: 0, explain: 'Because public goods are non-excludable, people can use them without paying (free-ride), which means the private market has little incentive to provide them, often requiring government provision instead.', misconception: 'The free-rider problem explains why public goods tend to be under-provided by private markets, not over-provided by government.', tag: 'The mixed economy' },
    { q: 'Market failure occurs when:', options: ['Resources are allocated inefficiently by the free market', 'A business goes bankrupt', 'Government intervenes in a market', 'Prices rise due to inflation'], correct: 0, explain: 'Market failure is when the free market fails to allocate resources efficiently, which can justify government intervention.', misconception: 'Market failure is a broader concept about inefficient resource allocation, not simply a business closing down or general inflation.', tag: 'The mixed economy' },
    { q: 'Privatisation refers to:', options: ['The transfer of ownership of an organisation from the public sector to the private sector', 'The government taking over a private business', 'A business closing down permanently', 'A firm merging with a competitor'], correct: 0, explain: 'Privatisation is the process of selling or transferring a state-owned (public sector) organisation into private ownership.', misconception: 'Nationalisation, not privatisation, describes government taking over a business — privatisation moves ownership the other way.', tag: 'The mixed economy' },
    { q: 'A potential advantage of privatisation for consumers is:', options: ['Increased competition may lead to lower prices or better service', 'Guaranteed lower prices in every single case', 'The complete elimination of all market failure', 'Automatic pay rises for all workers'], correct: 0, explain: 'Privatisation can introduce competition, which may improve efficiency and choice for consumers, though outcomes vary by industry.', misconception: 'Privatisation does not guarantee lower prices or eliminate market failure — outcomes depend on the level of competition introduced.', tag: 'The mixed economy' },
    { q: 'External costs of production are best described as:', options: ['Costs of an economic activity that fall on third parties not directly involved', 'Costs paid directly by the producer, such as wages', 'Costs that only affect the buyer of a good', 'Profits earned by a business'], correct: 0, explain: 'External costs (negative externalities) are costs imposed on third parties who are not part of the transaction, such as pollution affecting local residents.', misconception: 'Costs paid directly by the producer, like wages or raw materials, are private costs, not external costs.', tag: 'Externalities' },
    { q: 'Which of the following is an example of an external cost of production?', options: ['Pollution from a factory affecting nearby residents', 'Wages paid to factory workers', 'Rent paid for factory premises', 'Profit earned by the factory owner'], correct: 0, explain: 'Pollution imposed on people who are not part of the production or consumption decision is a classic example of an external cost.', misconception: 'Wages, rent and profit are all private costs or returns directly linked to the firm’s own operations, not costs imposed on outside third parties.', tag: 'Externalities' },
    { q: 'An external benefit of consumption is best illustrated by:', options: ['Vaccination reducing disease spread and benefiting the wider community, not just the person vaccinated', 'A consumer enjoying a meal at a restaurant', 'A firm earning higher profits', 'A worker receiving a pay rise'], correct: 0, explain: 'Vaccination creates a positive externality — benefits (reduced disease spread) that extend to third parties beyond the individual who is vaccinated.', misconception: 'Personal enjoyment, profit and wages are private benefits that stay with the individual or firm directly involved, not benefits to unrelated third parties.', tag: 'Externalities' },
    { q: 'Social cost is calculated as:', options: ['Private cost plus external cost', 'Private cost minus external cost', 'External cost only', 'Private benefit plus external benefit'], correct: 0, explain: 'Social cost is the total cost to society, made up of the private cost to the producer plus any external cost imposed on third parties.', misconception: 'Social cost combines private and external costs together — it is not external cost alone, and it should not be confused with social benefit.', tag: 'Externalities' },
    { q: 'Social benefit is calculated as:', options: ['Private benefit plus external benefit', 'Private benefit minus external benefit', 'External benefit only', 'Private cost plus external cost'], correct: 0, explain: 'Social benefit is the total benefit to society, made up of the private benefit to the individual plus any external benefit gained by third parties.', misconception: 'Social benefit adds private and external benefit together, and should not be confused with the formula for social cost.', tag: 'Externalities' },
    { q: 'Goods and services that generate negative externalities, such as pollution, tend to be:', options: ['Overproduced and overconsumed relative to the socially optimal level, if left to the free market', 'Underproduced relative to the socially optimal level', 'Produced at exactly the socially optimal level by the free market', 'Unaffected by market failure'], correct: 0, explain: 'When producers and consumers ignore external costs, goods with negative externalities tend to be overproduced and overconsumed compared to what is socially optimal.', misconception: 'This is the opposite outcome to goods with positive externalities, such as education, which tend to be underprovided by the free market.', tag: 'Externalities' }
  ];

