  var ECO12_QUESTION_BANK = [
    { q: 'Which of the following is the factor of production described as natural resources used in production?', options: ['Land', 'Labour', 'Capital', 'Enterprise'], correct: 0, explain: 'Land refers to natural resources used in production, including raw materials, farmland and mineral deposits.', misconception: 'Labour is the human effort used in production, capital is man-made resources like machinery, and enterprise is the risk-taking and organisation of the other factors.', tag: 'Factors of production & sectors' },
    { q: 'Enterprise, as a factor of production, refers to:', options: ['The willingness to take risks, organise other factors of production and start a business', 'Money used to buy shares', 'Machinery and equipment used in production', 'Natural resources such as land'], correct: 0, explain: 'Enterprise is the factor of production that involves entrepreneurs taking risks, organising the other three factors, and making business decisions.', misconception: 'Enterprise is about the entrepreneurial function, not simply money (capital) or physical resources (land).', tag: 'Factors of production & sectors' },
    { q: 'A business that extracts raw materials directly from nature, such as mining or fishing, is part of which sector?', options: ['Primary', 'Secondary', 'Tertiary', 'Quaternary'], correct: 0, explain: 'The primary sector involves extracting raw materials directly from the earth or sea, such as farming, fishing and mining.', misconception: 'Processing those raw materials into finished goods is a secondary sector activity, not primary.', tag: 'Factors of production & sectors' },
    { q: 'As countries develop economically, employment typically shifts:', options: ['From the primary sector towards the secondary and then tertiary sectors', 'From the tertiary sector towards the primary sector', 'Away from all three sectors equally', 'Only within the primary sector'], correct: 0, explain: 'As economies develop, employment typically moves from primary sector activities (agriculture, extraction) towards manufacturing (secondary), and eventually towards services (tertiary).', misconception: 'This shift generally happens in one direction as economies develop — away from primary industries, not towards them.', tag: 'Factors of production & sectors' },
    { q: 'In most developed economies today, the largest share of employment is typically found in the:', options: ['Tertiary sector', 'Primary sector', 'Secondary sector', 'All three sectors equally'], correct: 0, explain: 'Developed economies are typically dominated by the tertiary (service) sector in terms of both output and employment.', misconception: 'The primary sector tends to employ a much larger share of the workforce in developing, not developed, economies.', tag: 'Factors of production & sectors' },
    { q: 'Productivity is best defined as:', options: ['Output per worker (or per unit of input) in a given time period', 'The total amount produced by an economy', 'The total revenue earned by a business', 'The number of workers employed by a firm'], correct: 0, explain: 'Productivity measures output per unit of input, such as output per worker per hour, rather than total output or total employment.', misconception: 'Productivity is a measure of efficiency (output relative to input), not simply total output or the size of the workforce.', tag: 'Productivity & division of labour' },
    { q: 'Investment in education and training is likely to improve labour productivity by:', options: ['Increasing workers’ skills and human capital', 'Reducing the size of the workforce', 'Automatically reducing wages', 'Reducing the quality of goods produced'], correct: 0, explain: 'Education and training build human capital — the skills and knowledge of workers — which tends to raise labour productivity.', misconception: 'Improving skills raises, rather than reduces, the value and productivity of the workforce.', tag: 'Productivity & division of labour' },
    { q: 'Division of labour refers to:', options: ['Breaking down a production process into smaller, specialised tasks carried out by different workers', 'Sharing all profits equally among workers', 'Employing only one worker per business', 'Combining all production tasks into a single job role'], correct: 0, explain: 'Division of labour involves splitting a production process into separate tasks, with each worker specialising in one part.', misconception: 'Division of labour is about task specialisation, not profit-sharing or reducing the workforce to a single role.', tag: 'Productivity & division of labour' },
    { q: 'A key advantage of division of labour for a business is:', options: ['Increased output through worker specialisation and practice', 'Guaranteed higher wages for all staff', 'Elimination of all boredom for workers', 'Reduced need for any training at all'], correct: 0, explain: 'Specialisation allows workers to become highly skilled and efficient at a specific task, generally increasing output.', misconception: 'Division of labour can actually increase, not eliminate, worker boredom, since tasks become narrow and repetitive.', tag: 'Productivity & division of labour' },
    { q: 'A key disadvantage of division of labour for workers can be:', options: ['Work becoming repetitive and monotonous, reducing job satisfaction', 'Workers becoming more skilled overall', 'Increased variety in daily tasks', 'Guaranteed promotion for all staff'], correct: 0, explain: 'Because workers repeat the same narrow task, division of labour can make work monotonous and reduce job satisfaction.', misconception: 'Division of labour tends to narrow, not increase, the variety of tasks a worker performs.', tag: 'Productivity & division of labour' },
    { q: 'Total revenue is calculated as:', options: ['Price per unit multiplied by quantity sold', 'Total costs minus total fixed costs', 'Total costs plus profit', 'Quantity sold divided by price'], correct: 0, explain: 'Total revenue = price × quantity sold.', misconception: 'Total revenue is a sales calculation (price × quantity), not directly a costs calculation.', tag: 'Costs, revenue & profit calculations' },
    { q: 'Total costs are calculated as:', options: ['Total fixed costs plus total variable costs', 'Total revenue minus profit', 'Price multiplied by quantity', 'Average cost multiplied by fixed costs'], correct: 0, explain: 'Total costs = total fixed costs + total variable costs.', misconception: 'While total revenue minus profit also equals total costs, the standard definition combines fixed and variable costs directly.', tag: 'Costs, revenue & profit calculations' },
    { q: 'Fixed costs are best described as costs that:', options: ['Do not change with the level of output, such as rent', 'Change directly with the level of output, such as raw materials', 'Only occur when output is zero', 'Always equal total revenue'], correct: 0, explain: 'Fixed costs, such as rent or insurance, stay the same regardless of how much is produced, at least in the short run.', misconception: 'Costs that change directly with output, like raw materials or piece-rate wages, are variable costs, not fixed costs.', tag: 'Costs, revenue & profit calculations' },
    { q: 'Profit is calculated as:', options: ['Total revenue minus total costs', 'Total revenue plus total costs', 'Total costs minus fixed costs', 'Price divided by quantity'], correct: 0, explain: 'Profit = total revenue − total costs.', misconception: 'Profit is the difference between revenue and costs, not their sum.', tag: 'Costs, revenue & profit calculations' },
    { q: 'A business selling 500 units at $10 each, with total costs of $3,500, makes a profit of:', options: ['$1,500', '$5,000', '$3,500', '$8,500'], correct: 0, explain: 'Total revenue = 500 × $10 = $5,000. Profit = $5,000 − $3,500 = $1,500.', misconception: 'A common error is forgetting to subtract total costs from total revenue, or miscalculating total revenue itself.', tag: 'Costs, revenue & profit calculations' },
    { q: 'Economies of scale refer to:', options: ['Falling average costs of production as output increases', 'Rising average costs of production as output increases', 'A business making a loss', 'A reduction in total revenue'], correct: 0, explain: 'Economies of scale occur when average costs of production fall as a business increases its scale of output.', misconception: 'Rising average costs as output grows describes diseconomies of scale, the opposite effect.', tag: 'Economies of scale' },
    { q: 'Purchasing economies of scale arise because larger firms can:', options: ['Buy raw materials in bulk at a lower price per unit', 'Automatically increase their prices', 'Avoid paying for raw materials entirely', 'Reduce the quality of their products'], correct: 0, explain: 'Larger firms can negotiate discounts for buying materials in bulk, reducing average costs — a purchasing (bulk-buying) economy of scale.', misconception: 'Purchasing economies are about lower unit costs from bulk buying, not about pricing strategy or product quality.', tag: 'Economies of scale' },
    { q: 'Financial economies of scale occur because larger firms:', options: ['Can often borrow money more cheaply due to being seen as lower risk', 'Always pay higher interest rates on loans', 'Cannot access any form of finance', 'Must pay all costs in cash upfront'], correct: 0, explain: 'Larger, more established firms are often viewed as lower-risk borrowers, allowing them to access finance at lower interest rates.', misconception: 'It is often assumed size makes borrowing harder, when in fact larger firms often benefit from cheaper access to finance.', tag: 'Economies of scale' },
    { q: 'External economies of scale occur when:', options: ['The whole industry grows, benefiting all firms within it, such as through a larger pool of skilled local labour', 'Only one specific firm grows and benefits internally', 'A firm reduces its own output', 'Government imposes new regulations'], correct: 0, explain: 'External economies of scale benefit all firms in an industry as the whole industry (not just one firm) grows in a particular area — for example, through a local skilled labour pool or good infrastructure.', misconception: 'Internal economies of scale come from a single firm growing, whereas external economies benefit the whole local industry.', tag: 'Economies of scale' },
    { q: 'Diseconomies of scale occur when:', options: ['Average costs rise as a business grows too large', 'Average costs fall as a business grows', 'A business closes down', 'Revenue exceeds costs'], correct: 0, explain: 'Diseconomies of scale happen when a business becomes so large that average costs start to rise, often due to management or communication problems.', misconception: 'Falling average costs as output grows describes economies of scale, the opposite of diseconomies.', tag: 'Diseconomies of scale & LRAC' },
    { q: 'Communication problems in very large firms can cause diseconomies of scale because:', options: ['Information can become distorted or delayed as it passes through many layers of management', 'Communication always improves as a firm grows', 'Large firms never need to communicate internally', 'It has no impact on costs'], correct: 0, explain: 'As firms grow very large, messages can become slower, distorted or lost through multiple layers of management, reducing efficiency and raising costs.', misconception: 'Growth does not automatically improve communication — very large organisations often struggle with it, raising average costs.', tag: 'Diseconomies of scale & LRAC' },
    { q: 'On a long-run average cost (LRAC) curve, the downward-sloping section shows:', options: ['Economies of scale, as average costs fall with rising output', 'Diseconomies of scale, as average costs rise with rising output', 'A business making a loss', 'Fixed costs only'], correct: 0, explain: 'The downward-sloping part of the LRAC curve shows average costs falling as output rises — economies of scale.', misconception: 'The upward-sloping section of the LRAC curve represents diseconomies of scale, not the downward-sloping part.', tag: 'Diseconomies of scale & LRAC' },
    { q: 'The minimum point of a long-run average cost (LRAC) curve represents:', options: ['The most efficient scale of production, with the lowest average cost', 'The point of maximum diseconomies of scale', 'The point where the business makes zero revenue', 'The point where fixed costs are highest'], correct: 0, explain: 'The lowest point on the LRAC curve is where average costs are minimised — the most productively efficient scale of output.', misconception: 'This point represents maximum efficiency (lowest cost), not maximum diseconomies, which occur further along the upward-sloping section.', tag: 'Diseconomies of scale & LRAC' },
    { q: 'A key advantage of competition for consumers is that it can lead to:', options: ['Lower prices, greater choice and higher quality', 'Guaranteed shortages of goods', 'Fewer businesses to choose from', 'Higher prices for all goods'], correct: 0, explain: 'Competition between firms tends to push prices down, encourage innovation and quality improvements, and increase consumer choice.', misconception: 'Competition tends to benefit, not harm, consumers through lower prices and more choice — the opposite of the stated outcomes.', tag: 'Competition & firm size' },
    { q: 'Which of the following is a potential advantage of large firms over small firms?', options: ['They can often benefit from economies of scale, lowering average costs', 'They always provide better customer service', 'They are always more innovative than small firms', 'They face no risk of diseconomies of scale'], correct: 0, explain: 'Large firms can often access economies of scale, such as bulk buying and cheaper finance, which small firms cannot.', misconception: 'Large firms are not automatically better at customer service or innovation, and they do risk diseconomies of scale if they grow too large.', tag: 'Competition & firm size' },
    { q: 'A reason a firm might choose to grow through takeovers is:', options: ['To quickly gain market share and reduce competition', 'To guarantee it will make a loss', 'Because it is a legal requirement', 'To reduce its total output to zero'], correct: 0, explain: 'Takeovers allow firms to grow quickly, gain market share and potentially reduce the number of competitors in a market.', misconception: 'Growth through takeover is a strategic choice made to expand and increase market power, not a legal obligation.', tag: 'Competition & firm size' },
    { q: 'A firm might choose to remain small if it:', options: ['Operates in a niche market with limited overall demand', 'Wants to maximise economies of scale', 'Has unlimited access to finance', 'Wants to dominate a large mass market'], correct: 0, explain: 'Firms operating in small, specialised (niche) markets may have limited scope to grow, so they remain small by choice or necessity.', misconception: 'Wanting economies of scale or to dominate a mass market would typically motivate a firm to grow larger, not stay small.', tag: 'Competition & firm size' },
    { q: 'A monopoly exists when:', options: ['A single firm dominates or controls the whole market for a good or service', 'Many firms compete for the same customers', 'A firm has no market power at all', 'Prices are set entirely by consumers'], correct: 0, explain: 'A monopoly describes a market situation where one firm dominates supply, giving it significant control over price and output.', misconception: 'A market with many competing firms describes competitive markets, not a monopoly.', tag: 'Monopoly' },
    { q: 'A monopolist is often described as a "price-maker" because:', options: ['It has enough market power to set or influence the market price', 'It must always accept the price set by the market', 'It is legally required to set the lowest price', 'It has no influence over price at all'], correct: 0, explain: 'Because a monopoly dominates the market, it has significant power to set or influence price, unlike a small firm in a highly competitive market that must accept the market price.', misconception: 'Firms with no market power are described as "price-takers" — the opposite of a monopolist’s position.', tag: 'Monopoly' },
    { q: 'Patents can act as a barrier to entry because they:', options: ['Give a firm the legal, exclusive right to produce a particular product or process, blocking rivals', 'Automatically lower a firm’s production costs', 'Force every firm to share their technology', 'Guarantee a firm will make a loss'], correct: 0, explain: 'A patent grants exclusive legal rights over an invention or process, preventing other firms from copying it and entering the market with the same product.', misconception: 'Patents block, rather than force the sharing of, technology — this exclusivity is exactly what makes them a barrier to entry.', tag: 'Monopoly' },
    { q: 'A potential disadvantage of monopoly for consumers is:', options: ['Higher prices and reduced choice due to a lack of competition', 'Guaranteed lower prices for every product', 'Unlimited consumer choice', 'Automatic improvements in quality'], correct: 0, explain: 'Without competitive pressure, a monopolist may charge higher prices, restrict output, and have less incentive to improve quality or choice.', misconception: 'Monopoly power tends to work against consumers through higher prices and less choice, not in their favour.', tag: 'Monopoly' },
    { q: 'A potential advantage of monopoly can be:', options: ['The ability to achieve significant economies of scale, potentially lowering costs', 'Guaranteed lower prices for consumers in every case', 'Zero risk of any inefficiency', 'Automatic increases in product variety'], correct: 0, explain: 'Because monopolies often operate on a large scale, they may benefit from economies of scale, which can (though don’t always) be passed on as lower costs.', misconception: 'Economies of scale are a potential benefit, but monopolies do not automatically pass on lower prices to consumers — that depends on whether the firm chooses to.', tag: 'Monopoly' },
    { q: 'An oligopoly is a market structure characterised by:', options: ['A small number of large firms dominating the market', 'Thousands of tiny firms with no market power', 'A single firm controlling the entire market', 'Perfect information for all consumers'], correct: 0, explain: 'An oligopoly is a market dominated by a small number of large firms, each with significant market share.', misconception: 'A market with thousands of small firms describes highly competitive markets, and a single dominant firm describes a monopoly, not an oligopoly.', tag: 'Oligopoly' },
    { q: 'Non-price competition in an oligopoly refers to firms competing through:', options: ['Branding, advertising and product differentiation rather than price alone', 'Constantly cutting prices to zero', 'Refusing to advertise at all', 'Ignoring product quality entirely'], correct: 0, explain: 'In an oligopoly, firms often avoid aggressive price competition and instead compete on branding, advertising, product features and quality.', misconception: 'Non-price competition is about methods other than price, not about avoiding advertising or ignoring quality.', tag: 'Oligopoly' },
    { q: 'Collusion between firms in an oligopoly occurs when they:', options: ['Secretly agree to fix prices or restrict output to increase their joint profits', 'Compete as aggressively as possible on price', 'Share all information publicly with consumers', 'Merge into a single legal entity'], correct: 0, explain: 'Collusion is a (often illegal) secret agreement between firms to fix prices, limit output, or otherwise reduce competition to boost their profits.', misconception: 'Collusion is about reducing, not increasing, competition — it is the opposite of firms competing aggressively on price.', tag: 'Oligopoly' },
    { q: 'A potential disadvantage of collusion for consumers is:', options: ['Higher prices, as firms act together rather than competing', 'Guaranteed lower prices for all goods', 'Increased product variety', 'Improved product quality in every case'], correct: 0, explain: 'When firms collude rather than compete, prices tend to be higher and consumer choice more limited than in a genuinely competitive market.', misconception: 'Collusion generally harms consumers through higher prices, rather than lowering them or improving variety and quality.', tag: 'Oligopoly' },
    { q: 'The demand for labour is described as a "derived demand" because:', options: ['It depends on the demand for the good or service that the labour helps to produce', 'Workers demand jobs directly from consumers', 'It is unrelated to the demand for any product', 'It is fixed regardless of product demand'], correct: 0, explain: 'Labour is demanded not for its own sake but because of the demand for the goods and services it helps produce — this is why it is called a derived demand.', misconception: 'Demand for labour is linked to product demand, not something separate or unrelated to it.', tag: 'Labour demand & supply' },
    { q: 'An increase in the availability of machines that can replace workers is likely to:', options: ['Reduce demand for labour, as machines substitute for workers', 'Automatically increase wages for all workers', 'Have no effect on demand for labour', 'Guarantee full employment'], correct: 0, explain: 'If machines can substitute for labour, firms may demand fewer workers, reducing the demand for labour in that role.', misconception: 'Greater availability of substitutes for labour tends to reduce, not increase, demand for workers.', tag: 'Labour demand & supply' },
    { q: 'An increase in the school-leaving age would generally:', options: ['Reduce the supply of labour in the short term, as young people stay in education longer', 'Increase the supply of labour immediately', 'Have no effect on the labour supply', 'Only affect the demand for labour'], correct: 0, explain: 'Raising the school-leaving age keeps young people in education for longer, delaying their entry into the workforce and reducing the current labour supply.', misconception: 'This change reduces, rather than increases, the immediate supply of labour, since fewer young people enter work straight away.', tag: 'Labour demand & supply' },
    { q: 'An ageing population, with a smaller proportion of working-age people, would tend to:', options: ['Reduce the supply of labour available to the economy', 'Increase the supply of labour without limit', 'Have no effect on labour supply', 'Only affect demand for labour, not supply'], correct: 0, explain: 'An ageing population with fewer people of working age reduces the overall pool of available labour, decreasing labour supply.', misconception: 'An ageing population tends to shrink, not expand, the available labour supply.', tag: 'Labour demand & supply' },
    { q: 'On a labour market diagram, the equilibrium wage is found where:', options: ['The labour demand curve intersects the labour supply curve', 'The demand curve is at its highest point', 'The supply curve touches the vertical axis', 'Wages are at their lowest possible level'], correct: 0, explain: 'Just like in a product market, the equilibrium wage in a labour market is where the demand for labour equals the supply of labour.', misconception: 'Equilibrium is defined by demand equalling supply, not by an arbitrary highest or lowest point on either curve.', tag: 'Labour market diagrams & trade unions' },
    { q: 'If demand for labour increases, with supply of labour unchanged, the equilibrium wage and quantity of labour employed would generally:', options: ['Both rise', 'Both fall', 'Wage rises while employment falls', 'Remain exactly the same'], correct: 0, explain: 'An increase in demand for labour shifts the labour demand curve right, raising both the equilibrium wage and the quantity of labour employed.', misconception: 'Both wage and employment move in the same direction when labour demand shifts, assuming labour supply is unchanged.', tag: 'Labour market diagrams & trade unions' },
    { q: 'A trade union is an organisation that:', options: ['Represents workers to negotiate better pay and working conditions', 'Represents only business owners', 'Sets government economic policy', 'Fixes the price of all goods in the economy'], correct: 0, explain: 'A trade union represents the collective interests of workers, typically negotiating with employers over pay, hours and working conditions.', misconception: 'Trade unions represent employees, not employers, and they do not set national economic policy.', tag: 'Labour market diagrams & trade unions' },
    { q: 'A potential effect of successful trade union negotiation is:', options: ['Higher wages and/or improved working conditions for members', 'Guaranteed job losses for all members', 'Automatic reduction in company profits to zero', 'Elimination of all workplace regulation'], correct: 0, explain: 'Trade unions negotiate collectively on behalf of workers, which can result in higher wages or better working conditions, though this can also raise employer costs.', misconception: 'Successful negotiation aims to benefit members through pay and conditions, not to guarantee job losses.', tag: 'Labour market diagrams & trade unions' },
    { q: 'A government could deal with the external costs of pollution by:', options: ['Imposing a tax on the polluting activity to reduce it', 'Banning all taxation on businesses', 'Removing all environmental regulation', 'Ignoring the issue entirely'], correct: 0, explain: 'A tax on a polluting activity raises its cost, which should discourage the activity and help account for its external cost.', misconception: 'Reducing regulation or removing taxes would tend to worsen, not correct, the market failure caused by pollution.', tag: 'Government intervention: externalities & competition' },
    { q: 'A subsidy could be used by government to encourage activities with positive externalities, such as:', options: ['Education or public transport', 'Cigarette production', 'Air pollution', 'Illegal activities'], correct: 0, explain: 'Subsidies lower the cost of producing or consuming goods with positive externalities, such as education, encouraging more of the activity.', misconception: 'Subsidies are used to encourage beneficial activities with positive externalities, not harmful ones with negative externalities like pollution.', tag: 'Government intervention: externalities & competition' },
    { q: 'Tradeable pollution permits work by:', options: ['Setting a limit on total pollution and allowing firms to buy and sell permits to pollute within that limit', 'Banning all pollution immediately with no transition period', 'Giving firms unlimited rights to pollute for free', 'Removing all government involvement in environmental policy'], correct: 0, explain: 'Pollution permit schemes cap total allowable pollution and let firms trade permits, creating a financial incentive to reduce emissions.', misconception: 'Permits set a limit and create a market for the right to pollute within it — they do not grant unlimited free pollution rights.', tag: 'Government intervention: externalities & competition' },
    { q: 'Government regulation can help limit monopoly power by:', options: ['Restricting anti-competitive behaviour and controlling mergers that would reduce competition', 'Guaranteeing one firm controls the entire market', 'Removing all consumer protection laws', 'Preventing any firm from ever growing'], correct: 0, explain: 'Regulators can block anti-competitive mergers and prevent abuse of monopoly power to protect competition and consumers.', misconception: 'Regulation aims to limit, not guarantee, dominant market power, and it does not ban firms from growing altogether — only anti-competitive behaviour.', tag: 'Government intervention: externalities & competition' },
    { q: 'A national minimum wage is:', options: ['The lowest hourly wage rate that employers are legally allowed to pay most workers', 'The highest wage a business can legally pay', 'A wage set individually by each business with no legal requirement', 'A tax on workers’ income'], correct: 0, explain: 'A minimum wage is a legally enforced wage floor — the lowest amount an employer can pay covered workers per hour.', misconception: 'A minimum wage sets a floor, not a ceiling, on pay, and it is set by government/law, not voluntarily chosen by each business.', tag: 'Minimum wage' },
    { q: 'A potential advantage of a minimum wage is that it can:', options: ['Reduce poverty among low-paid workers by raising their income', 'Guarantee zero unemployment', 'Automatically increase all businesses’ profits', 'Eliminate the need for any welfare support'], correct: 0, explain: 'By raising the pay floor for low-paid workers, a minimum wage can help reduce in-work poverty and improve living standards.', misconception: 'A minimum wage helps address low pay, but it does not guarantee full employment or automatically boost business profits.', tag: 'Minimum wage' },
    { q: 'A potential disadvantage of setting a minimum wage too high is that it could:', options: ['Cause unemployment, as some firms cut jobs due to higher labour costs', 'Guarantee higher output for every business', 'Automatically eliminate all poverty', 'Reduce all business costs to zero'], correct: 0, explain: 'If set too high, a minimum wage can raise labour costs sharply, potentially leading some firms to reduce staff or hiring, causing unemployment.', misconception: 'A very high minimum wage risks job losses through higher costs, rather than automatically eliminating poverty or reducing costs.', tag: 'Minimum wage' },
    { q: 'On a labour market diagram, introducing a minimum wage above the market equilibrium wage would typically create:', options: ['Excess supply of labour (unemployment), as more people want to work than firms want to hire', 'Excess demand for labour', 'No change to the labour market at all', 'A lower equilibrium wage'], correct: 0, explain: 'Setting a minimum wage above equilibrium increases the quantity of labour supplied while reducing the quantity demanded by firms, creating excess supply — unemployment.', misconception: 'A minimum wage set above equilibrium causes excess supply of labour (more people wanting jobs than are available), not excess demand.', tag: 'Minimum wage' }
  ];

