  var ECO22_QUESTION_BANK = [
    { q: 'Globalisation is best defined as:', options: ['The increasing integration and interdependence of economies around the world', 'A single country becoming completely self-sufficient', 'A fall in international trade', 'A tax on imported goods'], correct: 0, explain: 'Globalisation describes the growing interconnection between economies through trade, investment, communication and the movement of people, goods and money.', misconception: 'Globalisation is about countries becoming more connected, not more self-sufficient or isolated, and it is not itself a tax.', tag: 'Globalisation' },
    { q: 'A fall in transport costs, such as through container shipping, tends to:', options: ['Increase globalisation by making international trade cheaper and easier', 'Decrease globalisation by making trade more expensive', 'Have no effect on international trade', 'Only affect trade between neighbouring countries'], correct: 0, explain: 'Cheaper transport reduces the cost of moving goods internationally, encouraging more trade and deeper global integration.', misconception: 'Lower transport costs encourage, rather than discourage, international trade and therefore increase, not decrease, globalisation.', tag: 'Globalisation' },
    { q: 'A benefit of globalisation for consumers can be:', options: ['Access to a wider range of goods at potentially lower prices', 'Guaranteed job security in every industry', 'The complete elimination of all competition', 'Higher prices in every market'], correct: 0, explain: 'Globalisation can increase competition and choice, often lowering prices and widening the range of goods available to consumers.', misconception: 'Globalisation tends to increase competition rather than eliminate it, and it can put some domestic jobs at risk even while benefiting consumers overall.', tag: 'Globalisation' },
    { q: 'A potential drawback of globalisation for a domestic economy is:', options: ['Traditional industries may struggle to compete with cheaper imports, leading to job losses', 'Guaranteed economic growth every year', 'Complete elimination of environmental problems', 'No effect on domestic employment at all'], correct: 0, explain: 'Increased international competition from globalisation can cause traditional or less competitive domestic industries to decline, leading to job losses.', misconception: 'Globalisation brings both benefits and costs — it does not guarantee growth or automatically solve environmental problems.', tag: 'Globalisation' },
    { q: 'A multinational corporation (MNC) is best described as a business that:', options: ['Owns or operates production or service facilities in more than one country', 'Only trades within its home country', 'Is always owned entirely by one government', 'Cannot employ any foreign workers'], correct: 0, explain: 'An MNC operates in multiple countries, often with headquarters in one country and production or sales facilities in others.', misconception: 'Operating only within one country would describe a domestic firm, not a multinational corporation.', tag: 'MNCs & foreign direct investment (FDI)' },
    { q: 'Foreign direct investment (FDI) refers to:', options: ['Investment by a firm or individual from one country into business operations located in another country', 'A government’s domestic tax revenue', 'A loan given between two individuals in the same country', 'A tariff imposed on imports'], correct: 0, explain: 'FDI is investment made by a company or individual in one country into business assets or operations in another country, such as building a factory abroad.', misconception: 'FDI specifically involves cross-border investment in business operations, not domestic tax revenue or a tariff.', tag: 'MNCs & foreign direct investment (FDI)' },
    { q: 'A reason an MNC might locate production overseas is to:', options: ['Access cheaper raw materials, labour, or other resources in that country', 'Increase its transport costs unnecessarily', 'Avoid ever selling to customers in that country', 'Guarantee it pays more tax'], correct: 0, explain: 'MNCs often locate overseas to access cheaper resources, labour, or materials, helping to reduce their overall costs.', misconception: 'Overseas location decisions are usually about reducing costs or accessing new markets, not about increasing costs or avoiding sales.', tag: 'MNCs & foreign direct investment (FDI)' },
    { q: 'A potential benefit of FDI for a host economy is:', options: ['Job creation and investment in infrastructure', 'Guaranteed elimination of all local competition', 'Automatic environmental improvement', 'Reduced government tax revenue in every case'], correct: 0, explain: 'FDI can create jobs, bring investment into infrastructure, and help develop skills and capital in the host economy.', misconception: 'FDI has both potential benefits and drawbacks (such as profit repatriation or environmental impact) — it does not automatically eliminate competition or guarantee lower tax revenue.', tag: 'MNCs & foreign direct investment (FDI)' },
    { q: 'A potential drawback of MNC activity for a host country is:', options: ['Profits may be sent back (repatriated) to the MNC’s home country rather than reinvested locally', 'MNCs never create any jobs', 'MNCs always pay more tax than domestic firms', 'MNCs cannot cause any environmental damage'], correct: 0, explain: 'MNCs may repatriate (send home) a large share of profits rather than reinvesting them in the host economy, limiting the local benefit.', misconception: 'MNCs do typically create jobs, but a common criticism is that profits often leave the host country rather than being reinvested there.', tag: 'MNCs & foreign direct investment (FDI)' },
    { q: 'A benefit of free trade for consumers is:', options: ['Access to a wider range of goods, often at lower prices, due to increased competition', 'Guaranteed elimination of all imports', 'Automatic increases in the price of every good', 'A reduction in consumer choice'], correct: 0, explain: 'Free trade increases competition from foreign producers, which can widen choice and reduce prices for consumers.', misconception: 'Free trade increases, rather than eliminates, the flow of imports, and it tends to increase, not reduce, consumer choice.', tag: 'Free trade & protection' },
    { q: 'A reason a government might introduce protectionist policies is to:', options: ['Protect domestic jobs and industries from foreign competition', 'Guarantee lower prices for consumers in every market', 'Eliminate all trade with every other country immediately', 'Increase competition from foreign firms'], correct: 0, explain: 'Governments may use protectionist measures to shield domestic industries and jobs from being undercut by foreign competition.', misconception: 'Protectionism typically reduces, not increases, competition from abroad, and it is usually more targeted than eliminating all trade.', tag: 'Free trade & protection' },
    { q: '"Dumping" in international trade refers to:', options: ['A country selling goods abroad at a price below their cost of production, harming foreign competitors', 'The act of a country banning all imports', 'A tax placed on exported goods', 'A country buying goods only from itself'], correct: 0, explain: 'Dumping occurs when a country exports goods at a price below their production cost, often to undercut foreign competitors — a common reason for protectionist retaliation.', misconception: 'Dumping is about underpricing exports unfairly, not about banning imports or taxing exports.', tag: 'Free trade & protection' },
    { q: 'A reason a government might protect an "infant industry" is to:', options: ['Give a new, developing domestic industry time to grow and become competitive before facing full foreign competition', 'Ensure the industry never grows at all', 'Guarantee the industry always makes a loss', 'Remove the industry from the domestic economy entirely'], correct: 0, explain: 'Infant industry protection shields a new domestic industry that is not yet efficient enough to compete internationally, allowing it time to develop.', misconception: 'The purpose of this protection is to help the industry grow and eventually compete, not to prevent growth or eliminate the industry.', tag: 'Free trade & protection' },
    { q: 'A tariff is best defined as:', options: ['A tax imposed on imported goods, raising their price', 'A limit on the physical quantity of a good that can be imported', 'A payment made to domestic producers by government', 'A tax on exported goods only'], correct: 0, explain: 'A tariff is a tax placed on imports, which raises their price and makes domestic goods relatively more competitive.', misconception: 'A physical limit on import quantity describes a quota, a different method of protection from a tariff.', tag: 'Methods of protection' },
    { q: 'A quota is best defined as:', options: ['A physical limit on the quantity of a good that can be imported into a country', 'A tax placed on all imported goods', 'A payment made to exporters', 'A ban on all foreign investment'], correct: 0, explain: 'A quota restricts the physical amount of a good that can be imported, regardless of price.', misconception: 'A quota limits quantity directly, unlike a tariff, which works by raising the price of imports through taxation.', tag: 'Methods of protection' },
    { q: 'A subsidy paid to domestic producers, used as a method of protection, works by:', options: ['Lowering domestic producers’ costs, allowing them to compete more effectively with cheaper imports', 'Directly taxing imported goods', 'Setting a physical limit on imports', 'Banning all foreign competition immediately'], correct: 0, explain: 'A subsidy reduces the costs faced by domestic producers, helping them to compete with lower-priced imports without directly taxing or limiting those imports.', misconception: 'A subsidy works by supporting domestic producers’ costs, unlike a tariff (which taxes imports) or a quota (which limits import quantity).', tag: 'Methods of protection' },
    { q: 'A disadvantage of tariffs for domestic consumers is that they:', options: ['Raise the price of imported goods, which consumers ultimately pay for', 'Always reduce the price of every good', 'Guarantee more choice for consumers', 'Have no effect on the price of imports'], correct: 0, explain: 'Tariffs increase the cost of importing goods, and this cost is often passed on to consumers through higher prices.', misconception: 'Tariffs tend to raise, not lower, prices for consumers, and they generally reduce the range of competitively priced imports available.', tag: 'Methods of protection' },
    { q: 'A trading bloc is best described as:', options: ['A group of countries that agree to reduce or remove trade barriers between themselves', 'A single company that trades internationally', 'A tax imposed by one country on all its trading partners', 'A country that refuses to trade with any other nation'], correct: 0, explain: 'A trading bloc is a group of countries that agree to trade more freely with each other, often by removing tariffs and other trade barriers between members.', misconception: 'A trading bloc is an agreement between multiple countries, not a single company or a unilateral tax policy.', tag: 'Trading blocs, WTO & trade patterns' },
    { q: 'A potential disadvantage of trading blocs for non-member countries is that they may:', options: ['Face higher barriers or reduced competitiveness when trying to trade with bloc members', 'Automatically receive the same trade benefits as member countries', 'Be guaranteed free access to the bloc’s markets', 'Face no impact on their trade at all'], correct: 0, explain: 'Non-member countries can face relatively higher barriers or find it harder to compete with the tariff-free trade enjoyed within the bloc.', misconception: 'Non-members generally do not automatically receive the same trading benefits as members — that preferential treatment is limited to countries inside the bloc.', tag: 'Trading blocs, WTO & trade patterns' },
    { q: 'The World Trade Organization (WTO) primarily aims to:', options: ['Promote free and fair international trade and help resolve trade disputes between countries', 'Set the interest rate for every country in the world', 'Print currency for its member countries', 'Ban all forms of international trade'], correct: 0, explain: 'The WTO works to promote freer, fairer global trade, sets international trade rules, and provides a forum to resolve trade disputes between countries.', misconception: 'The WTO focuses on trade rules and disputes — it does not set interest rates or issue currency, which are the roles of central banks.', tag: 'Trading blocs, WTO & trade patterns' },
    { q: 'An exchange rate is best defined as:', options: ['The value of one currency expressed in terms of another currency', 'The total value of a country’s exports', 'The rate of interest set by a central bank', 'The rate of inflation in an economy'], correct: 0, explain: 'An exchange rate shows how much of one currency is needed to buy a unit of another currency.', misconception: 'An exchange rate is specifically about the relative value of currencies, not export values, interest rates, or inflation directly.', tag: 'Exchange rate determination' },
    { q: 'A rise in a country’s interest rates, relative to other countries, would typically:', options: ['Increase demand for that country’s currency, as investors seek higher returns', 'Decrease demand for that country’s currency', 'Have no effect on currency demand', 'Automatically cause deflation'], correct: 0, explain: 'Higher interest rates attract foreign investors seeking better returns, increasing demand for the currency and putting upward pressure on its value.', misconception: 'Higher interest rates tend to increase, not decrease, demand for a currency by making saving in that currency more attractive to foreign investors.', tag: 'Exchange rate determination' },
    { q: 'Currency speculators can affect exchange rates by:', options: ['Buying or selling large amounts of currency based on expectations of future value changes', 'Only trading physical goods, never currency', 'Being legally banned from all currency markets', 'Having no impact on supply or demand for currency'], correct: 0, explain: 'Speculators buy and sell currencies based on expectations about future movements, and these large-scale trades can significantly affect exchange rates.', misconception: 'Speculators specifically trade currency (not goods), and their activity can have a real, sometimes significant, impact on exchange rates.', tag: 'Exchange rate determination' },
    { q: 'Appreciation of a currency refers to:', options: ['A rise in the value of a currency, usually under a floating exchange rate system', 'A fall in the value of a currency', 'A government fixing the exchange rate at a new lower level', 'A currency losing all of its value'], correct: 0, explain: 'Appreciation is an increase in a currency’s value relative to other currencies, typically occurring under a floating exchange rate.', misconception: 'A fall in currency value would be depreciation, the opposite of appreciation.', tag: 'Appreciation & revaluation' },
    { q: 'If a country’s currency appreciates, its exports are likely to become:', options: ['More expensive for foreign buyers, potentially reducing demand for exports', 'Cheaper for foreign buyers', 'Completely unaffected in price', 'Illegal to sell abroad'], correct: 0, explain: 'When a currency appreciates, goods priced in that currency become more expensive for foreign buyers using other currencies, which can reduce export demand.', misconception: 'Appreciation makes exports more, not less, expensive abroad — this is the opposite effect to a depreciation.', tag: 'Appreciation & revaluation' },
    { q: 'If a country’s currency appreciates, imports into that country are likely to become:', options: ['Cheaper, potentially increasing demand for imports', 'More expensive', 'Completely banned', 'Unaffected in price'], correct: 0, explain: 'A stronger (appreciated) currency makes foreign goods relatively cheaper to buy, which can increase demand for imports.', misconception: 'Appreciation makes imports cheaper, not more expensive — again, the opposite effect to depreciation.', tag: 'Appreciation & revaluation' },
    { q: 'A likely effect of currency appreciation on the current account is that it may:', options: ['Worsen the current account, as exports fall and imports rise', 'Improve the current account, as exports rise and imports fall', 'Have no effect on the current account at all', 'Guarantee a current account surplus'], correct: 0, explain: 'As appreciation tends to make exports more expensive and imports cheaper, it can reduce export revenue and increase import spending, worsening the current account.', misconception: 'Appreciation tends to worsen, not improve, the current account balance — depreciation has the improving effect instead.', tag: 'Appreciation & revaluation' },
    { q: 'Depreciation of a currency refers to:', options: ['A fall in the value of a currency, usually under a floating exchange rate system', 'A rise in the value of a currency', 'A government fixing the exchange rate at a higher level', 'The complete removal of a currency from circulation'], correct: 0, explain: 'Depreciation is a decrease in a currency’s value relative to other currencies under a floating exchange rate.', misconception: 'A rise in currency value would be appreciation, the opposite of depreciation.', tag: 'Depreciation & devaluation' },
    { q: 'If a country’s currency depreciates, its exports are likely to become:', options: ['Cheaper for foreign buyers, potentially increasing demand for exports', 'More expensive for foreign buyers', 'Completely unaffected in price', 'Illegal to sell abroad'], correct: 0, explain: 'A weaker (depreciated) currency makes goods priced in that currency cheaper for foreign buyers, which can boost export demand.', misconception: 'Depreciation makes exports cheaper, not more expensive, for foreign buyers — the opposite of the effect of appreciation.', tag: 'Depreciation & devaluation' },
    { q: 'If a country’s currency depreciates, imports into that country are likely to become:', options: ['More expensive, potentially reducing demand for imports', 'Cheaper', 'Completely banned', 'Unaffected in price'], correct: 0, explain: 'A weaker currency makes foreign goods more expensive to buy, which can reduce demand for imports.', misconception: 'Depreciation makes imports more expensive, not cheaper — this is the opposite effect to appreciation.', tag: 'Depreciation & devaluation' },
    { q: 'A likely effect of currency depreciation on the current account is that it may:', options: ['Improve the current account, as exports become more competitive and imports more expensive', 'Worsen the current account, as exports fall and imports rise', 'Have no effect on the current account at all', 'Guarantee a current account deficit'], correct: 0, explain: 'Depreciation tends to make exports cheaper (boosting export revenue) and imports more expensive (reducing import spending), which can improve the current account balance.', misconception: 'Depreciation tends to improve, not worsen, the current account — appreciation has the worsening effect instead.', tag: 'Depreciation & devaluation' },
    { q: 'Devaluation differs from depreciation in that devaluation:', options: ['Is a deliberate decision by a government or central bank to lower the value of a fixed exchange rate', 'Only happens under a freely floating exchange rate', 'Always increases the value of a currency', 'Cannot be controlled by any authority'], correct: 0, explain: 'Devaluation is a deliberate policy action to lower the value of a currency under a fixed or managed exchange rate system, whereas depreciation happens through market forces under a floating exchange rate.', misconception: 'Devaluation is a government/central bank decision under a fixed system, not something that happens automatically through the free market as depreciation does.', tag: 'Depreciation & devaluation' }
  ];

